#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <functional>
#include <utility>
#include <cstdlib>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    cin >> h >> w;
    vector<vector<long long>> a(h, vector<long long>(w));
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            cin >> a[i][j];
        }
    }

    const long long INF = 1000000000000000000LL;
    vector<vector<long long>> best(h, vector<long long>(w, INF));
    best[0][0] = 0;
    typedef pair<long long, pair<int, int>> Item;
    priority_queue<Item, vector<Item>, greater<Item>> heap;
    heap.push({0, {0, 0}});
    int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
    while (!heap.empty()) {
        Item top = heap.top();
        heap.pop();
        long long effort = top.first;
        int x = top.second.first, y = top.second.second;
        if (effort > best[x][y]) continue;
        for (int d = 0; d < 4; d++) {
            int p = x + dx[d], q = y + dy[d];
            if (p >= 0 && p < h && q >= 0 && q < w) {
                long long cost = max(effort, llabs(a[p][q] - a[x][y]));
                if (cost < best[p][q]) {
                    best[p][q] = cost;
                    heap.push({cost, {p, q}});
                }
            }
        }
    }
    cout << best[h - 1][w - 1] << "\n";

    return 0;
}

